import type { HomePost } from "@/shared/types/home";

type PostCardProps = {
  post: HomePost;
};

export default function PostCard({ post }: PostCardProps) {
  return (
    <article className="card" style={{ width: "18rem" }}>
      <img className="card-img-top" src={post.capa} alt={post.titulo} />
      <div className="card-body">
        <p className="card-text mb-2">{post.categoria}</p>
        <h2 className="card-title h5">{post.titulo}</h2>
        <p className="card-text">{post.subtitulo}</p>
      </div>
    </article>
  );
}