"use client";

import { useEffect, useState } from "react";
import Formulario from "../components/Formulario";
import PostCard from "../components/PostCard";
import { getHomePosts } from "../api/HomeApi";
import type { HomePostsResponse } from "@/shared/types/home";

export default function HomePageView() {
  const [aluno, setAluno] = useState("Samuel");
  const [posts, setPosts] = useState<HomePostsResponse>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  async function loadPosts() {
    setIsLoading(true);
    setError(null);

    try {
      const postsData = await getHomePosts();
      setPosts(postsData);
    } catch (err) {
      console.error("Erro ao buscar posts:", err);
      setError("Não foi possível carregar os posts. Tente novamente.");
    } finally {
      setIsLoading(false);
    }
  }

  useEffect(() => {
    void loadPosts();
  }, []);

  return (
    <>
      <h1 className="mb-3">Testes</h1>

      <div className="d-flex align-items-center gap-3 mb-3">
        <p className="mb-0">Aluno: {aluno}</p>
        <button
          className="btn btn-primary"
          type="button"
          onClick={() => setAluno("João")}
        >
          Alterar Aluno
        </button>
      </div>

      <Formulario />

      {isLoading && (
        <div className="alert alert-light border mb-3">Carregando posts...</div>
      )}

      {error && (
        <div className="alert alert-warning d-flex justify-content-between align-items-center mb-3">
          <span>{error}</span>
          <button
            className="btn btn-sm btn-outline-dark"
            type="button"
            onClick={() => void loadPosts()}
          >
            Tentar novamente
          </button>
        </div>
      )}

      {!isLoading && !error && posts.length > 0 && (
        <div className="d-flex flex-wrap gap-4">
          {posts.map((post) => (
            <PostCard key={post.id} post={post} />
          ))}
        </div>
      )}

      {!isLoading && !error && posts.length === 0 && (
        <div className="alert alert-light border">Nenhum post encontrado.</div>
      )}
    </>
  );
}
