import type { HomePostsResponse } from "../../../shared/types/home";
// import { BffConnectionFactory } from "../../../shared/infrastructure/bff/BffConnectionFactory";
import { HomeEndpoint } from "./homeEndpoints";

// const apiConnection = BffConnectionFactory.create();

export async function getHomePosts(): Promise<HomePostsResponse> {
    const response = await fetch(HomeEndpoint.Post);
    if (!response.ok) {
        throw new Error("Erro ao buscar posts");
    }
    return response.json();
}